#!/usr/bin/env bash
# Passphrase-protected script generated by bash-encrypter.sh
ENC_SALT='c0475b58bc606ad0'
ENC_PAYLOAD=''

ENC_ARGS=()
ENC_PASS=""
ENC_SAVE=0
ENC_SAVE_PATH=""

while [[ $# -gt 0 ]]; do
  case $1 in
    -p)
      [[ $# -ge 2 ]] || { echo "error: -p needs a passphrase" >&2; exit 1; }
      ENC_PASS=$2
      shift 2
      ;;
    --save-decrypted)
      ENC_SAVE=1
      shift
      ;;
    --save-decrypted=*)
      ENC_SAVE=1
      ENC_SAVE_PATH=${1#*=}
      shift
      ;;
    *)
      ENC_ARGS+=("$1")
      shift
      ;;
  esac
done

if [[ -z $ENC_PASS ]]; then
  read -rsp "Script Encrypted   Enter Passphrase: " ENC_PASS
  echo
fi

ENC_SRC=$(printf '%s' "$ENC_PAYLOAD" |
  BASHENC_PASS="$ENC_PASS" openssl enc -d -aes-256-cbc -pbkdf2 -iter 600000 -a -A \
    -S "$ENC_SALT" -pass env:BASHENC_PASS 2>/dev/null) || ENC_SRC=""

if [[ ${ENC_SRC%%$'\n'*} != "#BASHENC-OK" ]]; then
  echo "error: wrong passphrase" >&2
  exit 1
fi

if (( ENC_SAVE )); then
  [[ -n $ENC_SAVE_PATH ]] || ENC_SAVE_PATH="$(dirname -- "$0")/decrypted-$(basename -- "$0")"
  if [[ -e $ENC_SAVE_PATH ]]; then
    echo "error: $ENC_SAVE_PATH already exists" >&2
    exit 1
  fi
fi

# Write plaintext to a temp file (mode 0600, owned by current user) so the
# decrypted script runs as a normal bash script with full terminal/tty
# inheritance.  The old fd-3 sourcing method (bash -c '. /dev/fd/3') ran the
# script in a -c eval context which broke interactive features: wget progress
# bars, tty detection, and similar isatty() checks on child processes.
# The temp file is removed immediately after bash opens it; on Linux the
# kernel keeps the inode alive until the process closes it, so the plaintext
# is unlinked from the filesystem before a single line executes.
ENC_TMP=$(mktemp "${TMPDIR:-/tmp}/bashenc.XXXXXXXXXX")
trap 'rm -f -- "$ENC_TMP"' EXIT
(umask 077; printf '%s\n' "${ENC_SRC#*$'\n'}" > "$ENC_TMP")
bash -- "$ENC_TMP" "${ENC_ARGS[@]}"
ENC_RC=$?

if (( ENC_SAVE )); then
  (
    umask 077
    printf '%s\n' "${ENC_SRC#*$'\n'}" > "$ENC_SAVE_PATH"
  )
  echo "decrypted script saved to $ENC_SAVE_PATH" >&2
fi

exit $ENC_RC
